-- Migration 014: 15 real, local Miami organizations,
-- researched individually. Pure inserts with fixed ids - safe to re-run.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('a7000000-0000-4000-8000-000000000001', null, 'Miami-Dade County Animal Services', 'The county-run animal shelter system caring for thousands of dogs, cats, and other animals across Miami-Dade County each year.', 'https://www.miamidade.gov', 'https://www.google.com/s2/favicons?domain=www.miamidade.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000002', null, 'Humane Society of Greater Miami', 'A Miami animal welfare organization running shelter and adoption services, relying on volunteers for direct animal care and community outreach.', 'https://www.humanesocietymiami.org', 'https://www.google.com/s2/favicons?domain=www.humanesocietymiami.org&sz=128', 'animals', array['recurring'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000003', null, 'Friends of Miami Animals', 'A Miami rescue organization focused on finding homes for shelter animals, run largely by a dedicated volunteer base.', 'https://www.fomapets.org', 'https://www.google.com/s2/favicons?domain=www.fomapets.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000004', null, 'Zoo Miami', 'The largest zoo in Florida, home to hundreds of species and reliant on volunteers to support guest education and animal care support roles.', 'https://www.zoomiami.org', 'https://www.google.com/s2/favicons?domain=www.zoomiami.org&sz=128', 'animals', array['recurring'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000005', null, 'Feeding South Florida', 'The largest hunger-relief organization in South Florida, distributing food across Miami-Dade, Broward, Palm Beach, and Monroe counties.', 'https://www.feedingsouthflorida.org', 'https://www.google.com/s2/favicons?domain=www.feedingsouthflorida.org&sz=128', 'food', array['good for crews'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'both', false),
  ('a7000000-0000-4000-8000-000000000006', null, 'University of Miami Health System', 'The academic medical center of the University of Miami, running a structured High School Student Volunteer summer program each year.', 'https://umiamihealth.org', 'https://www.google.com/s2/favicons?domain=umiamihealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 15, 'United States', 'FL', 'Miami', true, true, 'one-time', false),
  ('a7000000-0000-4000-8000-000000000007', null, 'Baptist Health South Florida', 'The largest healthcare organization in South Florida, with volunteer programs across multiple hospital campuses in the Miami area.', 'https://baptisthealth.net', 'https://www.google.com/s2/favicons?domain=baptisthealth.net&sz=128', 'medicine', array['recurring'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000008', null, 'Florida Department of Health in Miami-Dade County', 'The county public health department, running a volunteer and internship program supporting community health initiatives across Miami-Dade.', 'https://miamidade.floridahealth.gov', 'https://www.google.com/s2/favicons?domain=miamidade.floridahealth.gov&sz=128', 'medicine', array['leadership role'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000009', null, 'Little Lighthouse Foundation', 'A Miami nonprofit running more than 20 programs across 90 partner hospitals, schools, and youth centers to bring activities and support to children in need.', 'https://thelittlelighthouse.org', 'https://www.google.com/s2/favicons?domain=thelittlelighthouse.org&sz=128', 'community', array['recurring'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000010', null, 'Breakthrough Miami', 'An academic enrichment nonprofit connecting motivated middle and high schoolers with near-peer tutoring, mentoring, and leadership opportunities.', 'https://breakthroughmiami.org', 'https://www.google.com/s2/favicons?domain=breakthroughmiami.org&sz=128', 'education', array['leadership role', 'counts for school hours'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000011', null, 'NAMI Miami-Dade County', 'The local chapter of the National Alliance on Mental Illness, running education, advocacy, and support programs across Miami-Dade County.', 'https://namimiami.org', 'https://www.google.com/s2/favicons?domain=namimiami.org&sz=128', 'medicine', array['leadership role'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'ongoing', false),
  ('a7000000-0000-4000-8000-000000000012', null, 'HandsOn Miami', 'A Miami volunteer engagement organization connecting individuals and groups to hundreds of hands-on service projects across the city each year.', 'https://www.handsonmiami.org', 'https://www.google.com/s2/favicons?domain=www.handsonmiami.org&sz=128', 'community', array['good for crews'], false, false, 14, 'United States', 'FL', 'Miami', true, true, 'both', false),
  ('a7000000-0000-4000-8000-000000000013', null, 'Miami-Dade County Parks, Recreation and Open Spaces', 'The county parks department running Volunteers in Parks programs and weekly Park Service Days across dozens of Miami-Dade locations.', 'https://www.miamidade.gov', 'https://www.google.com/s2/favicons?domain=www.miamidade.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'FL', 'Miami', true, true, 'both', false),
  ('a7000000-0000-4000-8000-000000000014', null, 'Clean Miami Beach', 'A Miami nonprofit focused on beach cleanups alongside broader environmental education, mentorship, and community engagement work.', 'https://cleanmiamibeach.org', 'https://www.google.com/s2/favicons?domain=cleanmiamibeach.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'FL', 'Miami', true, true, 'both', false),
  ('a7000000-0000-4000-8000-000000000015', null, 'Special Olympics Florida', 'The Florida chapter of Special Olympics, providing year-round sports training and competition for athletes with intellectual disabilities statewide.', 'https://www.specialolympicsflorida.org', 'https://www.google.com/s2/favicons?domain=www.specialolympicsflorida.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'FL', 'Miami', true, true, 'both', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('a8000000-0000-4000-8000-000000000001', 'a7000000-0000-4000-8000-000000000001', 'Volunteer with Miami-Dade Animal Services', 'animals', 'Volunteers can serve as adoption counselors, animal care helpers who feed and groom shelter pets, enrichment volunteers who walk and socialize dogs and cats, or mobile adoption volunteers who bring adoptable pets out into the community. It is a good option if you want variety across several different shelter roles.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.miamidade.gov/global/service.page?Mduid_service=ser159839177136735', 'https://www.miamidade.gov/global/service.page?Mduid_service=ser159839177136735', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000002', 'a7000000-0000-4000-8000-000000000002', 'Volunteer with the Humane Society of Greater Miami', 'animals', 'Volunteer roles include dog walking and socializing, cat socializing, toy sorting and distribution, grooming support, off-site adoption events, and local fundraisers. Everyone starts with an orientation presentation and application before their first shift.', array['recurring'], 14, false, false, true, '2-3 hrs', 'https://www.humanesocietymiami.org/volunteer-program/', 'https://www.humanesocietymiami.org/volunteer-program/', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000003', 'a7000000-0000-4000-8000-000000000003', 'Volunteer with Friends of Miami Animals', 'animals', 'Volunteers must be 16 or older, with younger volunteers welcome alongside a parent, and commit to about six months of service totaling roughly 100 hours. It is a serious, structured option if you want a real ongoing responsibility with a rescue organization.', array['recurring'], 16, false, false, true, '100 hrs total', 'https://www.fomapets.org/volunteer/', 'https://www.fomapets.org/volunteer/', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000004', 'a7000000-0000-4000-8000-000000000004', 'Volunteer at Zoo Miami', 'animals', 'Volunteers interpret animals for guests, assist the Critter Connection education team, and help prepare diets in the zoo kitchen. It is a great fit if you are interested in zoology, education, or animal care from an institutional perspective.', array['recurring'], 14, false, false, true, '2-3 hrs', 'https://www.zoomiami.org/volunteer', 'https://www.zoomiami.org/volunteer', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000005', 'a7000000-0000-4000-8000-000000000005', 'Volunteer with Feeding South Florida', 'food', 'Volunteers sort and pack donated food at the organization distribution center, helping move millions of pounds of food to families across South Florida each year. Groups and individuals are both welcome, and shifts are posted regularly throughout the year.', array['good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.feedingsouthflorida.org', 'https://www.feedingsouthflorida.org', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000006', 'a7000000-0000-4000-8000-000000000006', 'Join the UHealth High School Volunteer Program', 'medicine', 'High school students get hands-on exposure to hospital operations over the summer, supporting patients and staff across the UHealth system. It is a strong option if you are considering a healthcare career and want real academic-medical-center experience.', array['counts for school hours'], 15, false, false, true, 'Summer program', 'https://umiamihealth.org/en/patient-,-a-,-visitors/patients-,-a-,-families/volunteering-at-uhealth/summer-programs/high-school-student-volunteer', 'https://umiamihealth.org/en/patient-,-a-,-visitors/patients-,-a-,-families/volunteering-at-uhealth/summer-programs/high-school-student-volunteer', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000007', 'a7000000-0000-4000-8000-000000000007', 'Volunteer with Baptist Health South Florida', 'medicine', 'Teen volunteers support patients and staff across Baptist Health many facilities, with applications handled separately by each specific hospital location. It is a good option if you want to choose a hospital close to home rather than one central program.', array['recurring'], 16, false, false, true, 'Varies', 'https://baptisthealth.net/about-baptist-health/become-a-volunteer', 'https://baptisthealth.net/about-baptist-health/become-a-volunteer', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000008', 'a7000000-0000-4000-8000-000000000008', 'Volunteer with the Florida Department of Health', 'medicine', 'Volunteers and interns support the department community health programs, giving a look at public health work rather than hospital-based medicine. It is a good pick if you are curious about public health or epidemiology specifically.', array['leadership role'], 16, false, false, true, 'Varies', 'https://miamidade.floridahealth.gov/about-us/volunteer-program/index.html', 'https://miamidade.floridahealth.gov/about-us/volunteer-program/index.html', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000009', 'a7000000-0000-4000-8000-000000000009', 'Volunteer with Little Lighthouse Foundation', 'community', 'Volunteers support programs like Activity Hour at Nicklaus Children Hospital and other partner-site initiatives that bring games, crafts, and companionship to kids across Miami. It is a good fit if you want variety across many different partner locations.', array['recurring'], 14, false, false, true, 'Varies', 'https://thelittlelighthouse.org', 'https://thelittlelighthouse.org', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000010', 'a7000000-0000-4000-8000-000000000010', 'Become a Student Volunteer with Breakthrough Miami', 'education', 'Student volunteers help organize tutoring sessions, workshops, and special events, with a focus on near-peer mentoring where older students support younger ones. It is a strong option if you want leadership experience on top of straightforward tutoring.', array['leadership role', 'counts for school hours'], 14, false, false, true, 'Varies', 'https://breakthroughmiami.org/student-volunteers/', 'https://breakthroughmiami.org/student-volunteers/', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000011', 'a7000000-0000-4000-8000-000000000011', 'Volunteer with NAMI Miami-Dade', 'medicine', 'Volunteers support mental health education programs, advocacy events, and community outreach that reduce stigma and connect people to resources. It is a meaningful option if you specifically want to support mental health awareness.', array['leadership role'], 16, false, false, true, 'Varies', 'https://namimiami.org/get-involved/volunteer/', 'https://namimiami.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000012', 'a7000000-0000-4000-8000-000000000012', 'Find a HandsOn Miami Project', 'community', 'HandsOn Miami posts a wide range of one-time and recurring projects across many causes, so you can browse and pick whatever fits your schedule and interests. It is the best starting point if you are not sure yet which specific cause you want to focus on in Miami.', array['good for crews'], 14, false, false, true, 'Varies', 'https://www.handsonmiami.org', 'https://www.handsonmiami.org', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000013', 'a7000000-0000-4000-8000-000000000013', 'Volunteer at a Miami-Dade Park', 'environment', 'Park Service Days happen weekly at parks across the county, with family-friendly projects ranging from beautification and tree planting to environmental stewardship. It is one of the easiest ways to find an outdoor project close to home anywhere in Miami-Dade.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.miamidade.gov/global/service.page?Mduid_service=ser1539102476686691', 'https://www.miamidade.gov/global/service.page?Mduid_service=ser1539102476686691', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000014', 'a7000000-0000-4000-8000-000000000014', 'Join a Clean Miami Beach Cleanup', 'environment', 'Volunteers take part in regular beach cleanups along the Miami coastline, with the organization also running education and mentorship programs tied to ocean conservation. It is a great pick if you specifically want your service to protect the coastline.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://cleanmiamibeach.org/', 'https://cleanmiamibeach.org/', '2026-01-01T00:00:00Z', 'Miami', 'FL'),
  ('a8000000-0000-4000-8000-000000000015', 'a7000000-0000-4000-8000-000000000015', 'Coach or Volunteer with Special Olympics Florida', 'sports', 'Class A volunteers who have direct contact with athletes, including coaches, complete a background check and Protective Behaviors Training before getting started. It is a serious, rewarding option if you want a real coaching role and are ready for the training process.', array['recurring', 'leadership role'], 16, false, false, true, '1-2 hrs / week', 'https://www.specialolympicsflorida.org/get-involved/volunteer', 'https://www.specialolympicsflorida.org/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Miami', 'FL')
on conflict (id) do nothing;
